#include "logos_format.h"
#include <algorithm>
#include <cstring>
namespace logos {
Status lgo_begin(LgoBuilder*b){if(!b)return Status::InvalidArgument;*b=LgoBuilder{};return Status::Ok;}static Status add_field(LgoBuilder*b,u32 id,FieldType type,ByteSpan v,u8 flags){if(!b||!id||id<=b->last_field_id||(!v.data&&v.size))return Status::BadFieldOrder;size_t p=b->field_stream.size();b->field_stream.resize(p+16+(size_t)v.size,0);put_u32_le(b->field_stream.data()+p,id);b->field_stream[p+4]=(u8)type;b->field_stream[p+5]=flags;put_u16_le(b->field_stream.data()+p+6,0);put_u64_le(b->field_stream.data()+p+8,v.size);if(v.size)std::memcpy(b->field_stream.data()+p+16,v.data,(size_t)v.size);b->field_count++;b->last_field_id=id;return Status::Ok;}Status lgo_add_u64(LgoBuilder*b,u32 id,u64 v,u8 flags){u8 x[8];put_u64_le(x,v);return add_field(b,id,FieldType::U64,{x,8},flags);}Status lgo_add_utf8(LgoBuilder*b,u32 id,std::string_view s,u8 flags){ByteSpan x{(const u8*)s.data(),(u64)s.size()};if(!valid_utf8(x))return Status::InvalidUtf8;return add_field(b,id,FieldType::UTF8,x,flags);}Status lgo_add_bytes(LgoBuilder*b,u32 id,ByteSpan v,u8 flags){return add_field(b,id,FieldType::BYTES,v,flags);}Status lgo_add_digest(LgoBuilder*b,u32 id,const Digest256&d,u8 flags){return add_field(b,id,FieldType::DIGEST256,{d.bytes.data(),32},flags);}Status lgo_add_digest_list(LgoBuilder*b,u32 id,const std::vector<Digest256>&in,u8 flags){std::vector<Digest256>d=in;std::sort(d.begin(),d.end());for(size_t i=1;i<d.size();i++)if(d[i]==d[i-1])return Status::DuplicateField;Buffer v(4+d.size()*32);put_u32_le(v.data(),(u32)d.size());for(size_t i=0;i<d.size();i++)std::memcpy(v.data()+4+i*32,d[i].bytes.data(),32);return add_field(b,id,FieldType::DIGEST256_LIST,{v.data(),(u64)v.size()},flags);}Status lgo_finish(LgoBuilder*b,Buffer*out,Digest256*d){if(!b||!out)return Status::InvalidArgument;Digest256 h=sha256({b->field_stream.data(),(u64)b->field_stream.size()});out->assign(24+b->field_stream.size()+32,0);auto*p=out->data();p[0]='L';p[1]='G';p[2]='O';p[3]='1';put_u16_le(p+4,1);put_u16_le(p+6,24);put_u32_le(p+8,0);put_u32_le(p+12,b->field_count);put_u64_le(p+16,b->field_stream.size());if(!b->field_stream.empty())std::memcpy(p+24,b->field_stream.data(),b->field_stream.size());std::memcpy(p+24+b->field_stream.size(),h.bytes.data(),32);if(d)*d=h;return Status::Ok;}
Status lgo_validate(ByteSpan r){if(!r.data||r.size<56)return Status::BadLength;auto*p=r.data;if(std::memcmp(p,"LGO1",4))return Status::BadMagic;if(get_u16_le(p+4)!=1||get_u16_le(p+6)!=24)return Status::BadVersion;if(get_u32_le(p+8)!=0)return Status::Unsupported;u32 count=get_u32_le(p+12);u64 n=get_u64_le(p+16);if(24+n+32!=r.size)return Status::BadLength;u64 pos=24,end=24+n;u32 prev=0,seen=0;while(pos<end){if(end-pos<16)return Status::BadLength;u32 id=get_u32_le(p+pos);u8 t=p[pos+4],flags=p[pos+5];u16 reserved=get_u16_le(p+pos+6);u64 len=get_u64_le(p+pos+8);if(!id||id<=prev)return Status::BadFieldOrder;if(reserved)return Status::Unsupported;if(len>end-pos-16)return Status::BadLength;if(t<(u8)FieldType::U64||t>(u8)FieldType::DIGEST256_LIST){if(flags&FIELD_CRITICAL)return Status::UnknownCriticalField;}if(t==(u8)FieldType::U64&&len!=8)return Status::BadLength;if(t==(u8)FieldType::DIGEST256&&len!=32)return Status::BadLength;if(t==(u8)FieldType::UTF8&&!valid_utf8({p+pos+16,len}))return Status::InvalidUtf8;if(t==(u8)FieldType::DIGEST256_LIST){if(len<4)return Status::BadLength;u32 c=get_u32_le(p+pos+16);if(len!=4ull+(u64)c*32)return Status::BadLength;for(u32 i=1;i<c;i++)if(std::memcmp(p+pos+20+(i-1)*32,p+pos+20+i*32,32)>=0)return Status::BadFieldOrder;}prev=id;seen++;pos+=16+len;}if(pos!=end||seen!=count)return Status::BadLength;Digest256 h=sha256({p+24,n});return std::memcmp(h.bytes.data(),p+24+n,32)==0?Status::Ok:Status::BadDigest;}
Status lgo_parse(ByteSpan r,LgoObjectView*out){if(!out)return Status::InvalidArgument;auto st=lgo_validate(r);if(st!=Status::Ok)return st;*out=LgoObjectView{};out->bytes=r;u64 n=get_u64_le(r.data+16),pos=24,end=24+n;while(pos<end){FieldView f{};f.id=get_u32_le(r.data+pos);f.type=(FieldType)r.data[pos+4];f.flags=r.data[pos+5];u64 len=get_u64_le(r.data+pos+8);f.value={r.data+pos+16,len};out->fields.push_back(f);pos+=16+len;}std::memcpy(out->digest.bytes.data(),r.data+24+n,32);return Status::Ok;}const FieldView* lgo_find_field(const LgoObjectView&v,u32 id){for(auto&f:v.fields)if(f.id==id)return&f;return nullptr;}Status lgo_get_u64(const LgoObjectView&v,u32 id,u64*out){auto*f=lgo_find_field(v,id);if(!f)return Status::ObjectNotFound;if(f->type!=FieldType::U64||f->value.size!=8||!out)return Status::BadLength;*out=get_u64_le(f->value.data);return Status::Ok;}Status lgo_get_utf8(const LgoObjectView&v,u32 id,std::string*out){auto*f=lgo_find_field(v,id);if(!f)return Status::ObjectNotFound;if(f->type!=FieldType::UTF8||!out)return Status::BadLength;out->assign((const char*)f->value.data,(size_t)f->value.size);return Status::Ok;}Status lgo_get_digest(const LgoObjectView&v,u32 id,Digest256*out){auto*f=lgo_find_field(v,id);if(!f)return Status::ObjectNotFound;if(f->type!=FieldType::DIGEST256||f->value.size!=32||!out)return Status::BadLength;std::memcpy(out->bytes.data(),f->value.data,32);return Status::Ok;}Status lgo_get_digest_list(const LgoObjectView&v,u32 id,std::vector<Digest256>*out){auto*f=lgo_find_field(v,id);if(!f)return Status::ObjectNotFound;if(f->type!=FieldType::DIGEST256_LIST||!out||f->value.size<4)return Status::BadLength;u32 n=get_u32_le(f->value.data);if(f->value.size!=4ull+(u64)n*32)return Status::BadLength;out->resize(n);for(u32 i=0;i<n;i++)std::memcpy((*out)[i].bytes.data(),f->value.data+4+i*32,32);return Status::Ok;}
Status lgl_encode(EventType type,u64 seq,const Digest256&prev,const Digest256&payload,std::string_view target,Buffer*out,Digest256*eh){if(!out||target.empty())return Status::InvalidArgument;out->assign(152,0);auto*p=out->data();std::memcpy(p,"LGL1",4);put_u16_le(p+4,1);put_u16_le(p+6,120);put_u32_le(p+8,0);put_u32_le(p+12,(u32)type);put_u64_le(p+16,seq);std::memcpy(p+24,prev.bytes.data(),32);std::memcpy(p+56,payload.bytes.data(),32);Digest256 th=sha256({(const u8*)target.data(),(u64)target.size()});std::memcpy(p+88,th.bytes.data(),32);Digest256 h=sha256({p,120});std::memcpy(p+120,h.bytes.data(),32);if(eh)*eh=h;return Status::Ok;}Status lgl_validate(ByteSpan r){if(!r.data||r.size!=152)return Status::BadLength;if(std::memcmp(r.data,"LGL1",4))return Status::BadMagic;if(get_u16_le(r.data+4)!=1||get_u16_le(r.data+6)!=120)return Status::BadVersion;if(get_u32_le(r.data+8)!=0)return Status::Unsupported;u32 et=get_u32_le(r.data+12);if(et<1||et>6)return Status::Unsupported;Digest256 h=sha256({r.data,120});return std::memcmp(h.bytes.data(),r.data+120,32)==0?Status::Ok:Status::BadDigest;}Status lgl_parse(ByteSpan r,LglRecord*out){if(!out)return Status::InvalidArgument;auto st=lgl_validate(r);if(st!=Status::Ok)return st;*out=LglRecord{};out->event_type=get_u32_le(r.data+12);out->sequence=get_u64_le(r.data+16);std::memcpy(out->previous_event_hash.bytes.data(),r.data+24,32);std::memcpy(out->payload_object_digest.bytes.data(),r.data+56,32);std::memcpy(out->target_semantic_hash.bytes.data(),r.data+88,32);std::memcpy(out->event_hash.bytes.data(),r.data+120,32);return Status::Ok;}
}
